var settings=UnityEditor.AssetDatabase.LoadAssetAtPath<Asteroids.Spawning.AsteroidSpawnSettings>("Assets/Settings/Asteroids/SpawnSettings.asset");var path=UnityEditor.AssetDatabase.GetAssetPath(settings.meshInfos[0].mesh);var data=new System.Collections.Generic.List<object>();foreach(var asset in UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path)) if(asset is UnityEngine.Mesh mesh)data.Add(new {mesh.name,mesh.vertexCount,triangles=mesh.triangles.Length/3});
var ship=UnityEditor.AssetDatabase.LoadAssetAtPath<Ships.Ship>("Assets/Prefabs/Ships/Ship_1.prefab");var mf=ship.GetComponentInChildren<UnityEngine.MeshFilter>();return new {asteroids=data,ship=mf.sharedMesh.name,shipVertices=mf.sharedMesh.vertexCount};
